int.TryParse("17", out int a);
// true,  a = 17
int.TryParse(" 17 ", out int b);
// true,  b = 17 (Leerzeichen am Rand ok)
int.TryParse("17,5", out int c);
// false, c = 0
int.TryParse("abc", out int d);
// false, d = 0
int.TryParse("", out int e);
// false, e = 0
int.TryParse("-3", out int f);
// true,  f = -3

static string PruefeAlter(string eingabe)
{
    if (string.IsNullOrWhiteSpace(eingabe))
        return "Bitte gib dein Alter ein.";
    if (!int.TryParse(eingabe, out int alter))
        return "Das Alter muss eine "
             + "ganze Zahl sein.";
    if (alter < 0 || alter > 120)
        return "Das Alter muss zwischen "
             + "0 und 120 liegen.";
    return null;
}

// PruefeAlter("17")  -> null
// PruefeAlter("abc") -> "Das Alter muss
//                        eine ganze Zahl sein."
// PruefeAlter("150") -> "Das Alter muss
//                  zwischen 0 und 120 liegen."

private void BtnSpeichern_Click(
    object sender, RoutedEventArgs e)
{
    string fehler = PruefeAlter(txtAlter.Text);
    if (fehler != null)
    {
        MessageBox.Show(fehler, "Eingabefehler",
            MessageBoxButton.OK,
            MessageBoxImage.Warning);
        txtAlter.Focus();
        return;
    }
    // ... speichern
}

// Rückfrage vor dem Löschen
var antwort = MessageBox.Show(
    "Eintrag wirklich löschen?", "Löschen",
    MessageBoxButton.YesNo,
    MessageBoxImage.Question);
if (antwort == MessageBoxResult.Yes)
    lstEintraege.Items.Remove(
        lstEintraege.SelectedItem);

// Button nur aktiv, wenn Eingabe gültig
private void TxtAlter_TextChanged(
    object sender, TextChangedEventArgs e)
{
    btnSpeichern.IsEnabled =
        PruefeAlter(txtAlter.Text) == null;
}

